      "إذا كانت رتبة المصفوفة الأولى m x n ورتبة الثانية n x r، فإن رتبة المصفوفة الناتجة هي m x r.",
      "تختلف عملية ضرب المصفوفات عن جمعها وطرحها، حيث لا تُضرب العناصر المتناظرة مباشرة بل تُضرب الصفوف في الأعمدة.",
