      "درجة الرأس هي عدد الحافات التي تلتقي عنده، وتُصنف إلى درجات زوجية أو فردية.",
      "تحديد مجموعات الرؤوس والحافات والدرجات يُشكل الأساس الرياضي لتحليل الشبكات وحل مسائل الأمثلية كأقصر مسار."
